INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (13,4,1,'Peel the bananas, break into chunks, and freeze for at least 2 hours (or overnight) until solid. Frozen banana is what makes this thick - fresh banana gives you a thin, foamy drink.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (14,4,2,'Pour the milk into the blender first, then add the whey protein isolate (2 x 30 g scoops), the peanut butter, and finally the frozen banana chunks. Powder goes into liquid, never on top of the frozen fruit, or it clumps against the blender wall.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (15,4,3,'Blend on high until completely smooth and creamy, 80-110 seconds. Scrape the sides down once and blend again if you can still see pale powder streaks.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (16,4,4,'The whey keeps thickening as it hydrates. If it is too thick to pour, loosen with a splash more milk, 20-30 ml at a time, and pulse to combine.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (17,4,5,'Add a pinch of salt, pulse briefly, then taste. It should read sweet and nutty with the salt lifting the banana - if it tastes flat, add a second pinch.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (18,5,1,'Peel the bananas, break into chunks, and freeze for at least 2 hours (or overnight) until solid. Frozen banana is what makes this thick - fresh banana gives you a thin, foamy drink.',NULL,NULL,NULL);
