INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (61,10,1,'Toast pine nuts in a dry pan over medium heat, shaking frequently, until lightly golden and fragrant (2-3 minutes). Watch carefully — they burn quickly. Set aside to cool.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (62,10,2,'Add garlic and salt to a mortar. Pound to a smooth paste.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (63,10,3,'Add toasted pine nuts. Crush until broken down but still slightly textured.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (64,10,4,'Tear basil leaves into the mortar. Pound in batches, grinding in circular motions until leaves break down into the paste.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (65,10,5,'Add parmesan cheese. Work into the mixture until combined.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (66,10,6,'Slowly drizzle in olive oil while stirring with the pestle. Continue until you reach a loose, spoonable consistency.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (67,10,7,'Taste and adjust salt. Transfer to a jar, top with a thin layer of olive oil to preserve. Refrigerate up to 1 week.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (68,11,1,'Warm the water to lukewarm (about 37°C — comfortable to touch). Sprinkle yeast over the surface and let bloom for 5 minutes until foamy.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (69,11,2,'In a large bowl, combine bread flour and salt. Make a well in the center.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (70,11,3,'Pour in the yeast mixture and olive oil. Stir with a wooden spoon until a shaggy dough forms.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (71,11,4,'Turn out onto a floured surface. Knead for 8-10 minutes until smooth, elastic, and slightly tacky but not sticky. The dough should spring back when poked.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (72,11,5,'Form into a ball. Place in a lightly oiled bowl, cover with a damp tea towel or cling film.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (73,11,6,'Let rise in a warm spot for 1-2 hours until doubled in size.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (74,11,7,'Punch down the dough to release air. Divide into 4 equal portions (~190g each).',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (75,11,8,'Use immediately, or wrap individual portions tightly in cling film and freeze for up to 3 months. Thaw overnight in fridge before use.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (113,16,1,'Brine the chicken: Cut chicken thigh into 1-inch cubes. Dissolve 1 tbsp salt in 500ml cold water. Submerge chicken, refrigerate 15-20 minutes. Rinse and pat dry.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (114,16,2,'Make the marinade: In a bowl, combine minced garlic, grated ginger, soy sauce, honey, and olive oil. Whisk until honey dissolves. Toss brined chicken in marinade. Set aside while you prep other ingredients.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (115,16,3,'Start the rice: Rinse jasmine rice under cold water until water runs clear. Cook according to package directions with a pinch of salt. Keep warm.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (116,16,4,'Prep vegetables: Cut onion and red bell pepper into 1-inch chunks.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (117,16,5,'Make the peanut sauce: In a small saucepan over medium-low heat, combine coconut milk, peanut butter, soy sauce, Worcestershire, honey, and cumin. Whisk until smooth and peanut butter melts. Simmer 3-4 minutes.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (118,16,6,'Thicken the sauce: Mix cornflour with 1 tbsp cold water to make a slurry. Stir into the simmering sauce. Cook 1-2 minutes until glossy. Remove from heat, stir in lime juice. Taste and adjust.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (119,16,7,'Cook the vegetables: Heat a large pan or wok over medium-high heat with a drizzle of oil. Sauté onion and red pepper for 3-4 minutes until slightly charred but still crisp. Remove and set aside.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (120,16,8,'Cook the chicken: In the same pan over medium-high heat, cook marinated chicken pieces in a single layer. Don\'t crowd the pan. Cook 3-4 minutes per side until golden and cooked through (74°C internal).',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (121,16,9,'Combine: Return vegetables to the pan with the chicken. Toss briefly to combine.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (122,16,10,'Serve: Spoon chicken and vegetables over jasmine rice. Drizzle generously with peanut sauce.',NULL,NULL,NULL);
