INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (381,47,1,'Par-boil the potatoes: Peel and cut potatoes into thick chips (~2cm). Place in cold salted water, bring to boil, then simmer 8-10 minutes until just tender but not falling apart. Drain and let steam dry for 5 minutes.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (382,47,2,'Rough up the chips: Shake the drained chips gently in the colander to roughen the edges — this creates extra crispy surface area.',NULL,NULL,NULL);
