INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (384,47,4,'Prep the steak: Remove steaks from fridge 20 minutes before cooking. Pat completely dry with kitchen paper. Season generously with salt on both sides.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (385,47,5,'Sear the steak: Heat ½ tbsp olive oil in a heavy pan over high heat until smoking. Add steaks and cook 2-3 minutes per side for medium-rare (adjust for thickness and preference). Remove and rest on a warm plate for 5 minutes.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (386,47,6,'Cook the mushrooms: Slice mushrooms. In the same pan over medium-high heat, add remaining ½ tbsp olive oil. Add mushrooms and rosemary sprigs. Season with salt and pepper. Sauté 4-5 minutes until golden and tender.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (387,47,7,'Serve: Plate the rested steak with air-fried chips and rosemary mushrooms alongside.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (388,48,1,'Par-boil the potatoes: Peel and cut potatoes into thick chips (~2cm). Place in cold salted water, bring to boil, then simmer 8-10 minutes until just tender but not falling apart. Drain and let steam dry for 5 minutes.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (389,48,2,'Rough up the chips: Shake the drained chips gently in the colander to roughen the edges — this creates extra crispy surface area.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (390,48,3,'Season and air fry: Toss chips with 1.5 tbsp olive oil and a pinch of salt. Air fry at 200°C for 20-25 minutes, shaking halfway, until golden and crispy.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (391,48,4,'Prep the steak: Remove steaks from fridge 20 minutes before cooking. Pat completely dry with kitchen paper. Season generously with salt on both sides.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (392,48,5,'Sear the steak: Heat 1 tbsp olive oil in a heavy pan over high heat until smoking. Add steaks and cook 2-3 minutes per side for medium-rare (adjust for thickness and preference). Remove and rest on a warm plate for 5 minutes.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (393,48,6,'Cook the mushrooms: Slice mushrooms. In the same pan over medium-high heat, add remaining ½ tbsp olive oil. Add mushrooms and rosemary sprigs. Season with salt and pepper. Sauté 4-5 minutes until golden and tender.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (394,48,7,'Serve: Plate the rested steak with air-fried chips and rosemary mushrooms alongside.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (395,49,1,'Par-boil the potatoes: Peel and cut potatoes into thick chips (~2cm). Place in cold salted water, bring to boil, then simmer 8-10 minutes until just tender but not falling apart. Drain and let steam dry for 5 minutes.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (396,49,2,'Rough up the chips: Shake the drained chips gently in the colander to roughen the edges — this creates extra crispy surface area.',NULL,NULL,NULL);
