INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (399,49,5,'Sear the steak: Heat 1.5 tbsp olive oil in a heavy pan over high heat until smoking. Add steaks and cook 3-4 minutes per side for medium-rare (adjust for thickness and preference). Remove and rest on a warm plate for 5 minutes.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (400,49,6,'Cook the mushrooms: Slice mushrooms. In the same pan over medium-high heat, add remaining ½ tbsp olive oil. Add mushrooms and rosemary sprigs. Season with salt and pepper. Sauté 4-5 minutes until golden and tender.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (401,49,7,'Serve: Plate the rested steak with air-fried chips and rosemary mushrooms alongside.',NULL,NULL,NULL);
