INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (440,55,7,'Top each slice with a fried egg (2 per person).',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (441,55,8,'Grate fresh parmesan over the top (10g per person).',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (442,55,9,'Serve immediately.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (443,56,1,'Make the mash: Peel and chop potatoes into chunks. Boil in salted water 15-20 minutes until tender. Drain well.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (444,56,2,'Mash with 15g butter until smooth. Season lightly. Spread on a plate and refrigerate until cold.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (445,56,3,'Make the stuffing: Melt 30g butter in a pan over medium heat. Add diced onion and cook 6-7 minutes until soft and lightly golden.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (446,56,4,'Add Italian herbs and thyme. Stir for 30 seconds until fragrant.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (447,56,5,'Tip onion mixture into a bowl with 120g breadcrumbs. Pour over warm stock and mix well. Season with salt and pepper. Let cool completely.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (448,56,6,'Form the balls: Combine sausage meat, cold mash (~200g), and cooled stuffing in a large bowl. Mix thoroughly with your hands until evenly combined.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (449,56,7,'Roll into 12 balls, about golf-ball sized (~65g each). Chill 15 minutes to firm up.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (450,56,8,'Coat the balls: Set up breading station - beaten eggs in one bowl, 100g breadcrumbs in another.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (451,56,9,'Dip each ball in egg wash, then roll in breadcrumbs until fully coated.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (452,56,10,'Bake at 190C for 25-30 minutes until golden and cooked through (internal temp 74C).',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (474,60,1,'Warm 134ml milk until lukewarm (37°C). Sprinkle yeast over milk and let bloom for 5-10 minutes until frothy.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (475,60,2,'In a large bowl, whisk together 400g bread flour, 50g sugar, and 1½ tsp salt.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (476,60,3,'Make a well in the centre. Add 2 whole eggs and 2 egg yolks, then pour in the yeast mixture. Stir with a wooden spoon until a shaggy dough forms.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (477,60,4,'Turn dough onto a clean work surface (do not flour). Knead for 10-12 minutes using the slap-and-fold technique: stretch dough away from you, fold it back, slap it down, rotate 90°. Dough will be sticky at first but will become smooth and elastic.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (478,60,5,'Cut 140g softened butter into small cubes. With dough still on the surface, add butter a few pieces at a time, squeezing and kneading to incorporate. This takes 8-10 minutes. The dough will become slippery — keep working until butter is fully absorbed and dough is smooth, shiny, and passes the windowpane test.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (479,60,6,'Form dough into a ball and place in a lightly oiled bowl. Cover with cling film and leave at room temperature for 1.5-2 hours until doubled. Alternatively, refrigerate overnight for better flavour.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (480,60,7,'Punch down dough and turn onto a lightly floured surface. Divide into 12 equal pieces (approximately 70g each). Roll each piece into a tight ball by cupping your hand over it and moving in circular motions on an unfloured surface.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (481,60,8,'Place buns on a lined baking tray with 3cm spacing. Cover loosely with cling film and leave for 45 minutes to 1 hour until puffed and nearly doubled.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (482,60,9,'Preheat oven to 180°C (fan). Beat remaining egg with a pinch of salt. Gently brush each bun with egg wash, then sprinkle with sesame seeds.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (483,60,10,'Bake for 15-18 minutes until deep golden brown (internal temp 88-90°C). Cool on a wire rack for 10 minutes before serving.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (484,61,1,'In a large bowl, whisk 6 egg yolks with 70g sugar until pale, thick, and the mixture falls in ribbons (about 3-4 minutes by hand).',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (485,61,2,'Heat 500ml milk in a saucepan over medium heat until steaming and small bubbles form at the edges. Do not boil.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (486,61,3,'Temper the yolks: very slowly pour the hot milk into the egg mixture in a thin stream, whisking constantly. This prevents the eggs from scrambling.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (487,61,4,'Return the mixture to the saucepan. Cook over low heat, stirring constantly with a wooden spoon, until it reaches 80°C on a thermometer or coats the back of the spoon (run your finger through it — it should leave a clear line).',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (488,61,5,'Immediately remove from heat and strain through a fine sieve into a clean bowl to remove any lumps.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (489,61,6,'Stir in 1 tsp vanilla extract and 115ml whiskey while the mixture is still warm.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (490,61,7,'Cover with cling film (touching the surface to prevent a skin forming) and refrigerate for at least 4 hours, or overnight for best flavour.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (491,61,8,'Serve chilled in small glasses. Optionally top with freshly grated nutmeg.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (492,62,1,'Get a tall, narrow container — the cup that came with your immersion blender or a wide-mouth mason jar works perfectly. The container should be just slightly wider than the blender head.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (493,62,2,'Crack the egg into the bottom of the container. Add Dijon mustard, salt, sugar, white wine vinegar, and lemon juice directly on top of the egg.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (494,62,3,'Pour 240ml sunflower oil on top. Don\'t stir — let it sit in layers with the egg mixture at the bottom and oil floating on top.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (495,62,4,'Place the immersion blender at the very bottom of the container, making sure the blade is touching the egg. Press down firmly to create a seal.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (496,62,5,'Turn the blender on high and hold it at the bottom without moving for 10-15 seconds. You\'ll see mayo start to form at the bottom, pushing the oil up.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (497,62,6,'Slowly — very slowly — lift the blender upward through the remaining oil. The mayo will emulsify as you go. Once you reach the top, you can move the blender up and down to incorporate any remaining oil. Total time: about 60 seconds.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (498,62,7,'Taste and adjust salt if needed. Transfer to a clean jar. Refrigerate immediately and use within 1 week.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (499,63,1,'Air fry chips: Cut 400g potatoes into chips. Toss with 1 tbsp oil and salt. Air fry at 200°C for 20-25 minutes, shaking halfway through.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (500,63,2,'Make quick pickle relish: Finely dice 40g gherkins. Mix with 1 tsp white wine vinegar, 1 tsp sugar, ¼ tsp mustard seeds, ¼ tsp salt. Set aside 5-10 minutes.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (501,63,3,'Make Big Mac sauce: Combine 120g mayo, the pickle relish, 20g Dijon mustard, 1 tsp onion powder, 1 tsp garlic powder. Mix well and refrigerate.',NULL,62,'Make Big Mac sauce: Combine 120g store-bought mayo, the pickle relish, 20g Dijon mustard, 1 tsp onion powder, 1 tsp garlic powder. Mix well and refrigerate.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (502,63,4,'Prepare the buns: For each burger, use 2 buns. From bun 1, use the bottom as-is. From bun 2, slice the bottom horizontally to make the middle club + top. Save top domes for breadcrumbs or snacking.',NULL,60,'Prepare the buns: For each burger, use 2 store-bought brioche buns. From bun 1, use the bottom as-is. From bun 2, slice the bottom horizontally to make the middle club + top.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (503,63,5,'Toast buns: Toast all cut sides in a dry pan over medium heat until golden, about 1-2 minutes.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (504,63,6,'Prepare toppings: Finely dice the onion, shred lettuce into thin strips, slice 30g gherkins for topping.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (505,63,7,'Cook patties: Follow linked Burger Patties recipe or season and cook 4 thin patties (~113g each). High heat, 2-3 min first side. Flip, immediately add ~20g cheddar to each patty, cook 2-3 min more until cheese melts.',NULL,43,'Cook patties: Season 4 store-bought beef patties with salt and pepper. High heat, 2-3 min first side. Flip, immediately add ~20g cheddar to each patty, cook 2-3 min more until cheese melts.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (506,63,8,'Assemble bottom half: Bottom bun → sauce → lettuce → onion → cheesy patty.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (507,63,9,'Add middle and top: Middle bun (club) → sauce → lettuce → onion → gherkins → cheesy patty → top bun.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (508,63,10,'Serve immediately with air fried chips.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (509,63,11,'LAYER ORDER (bottom to top): Bottom bun | Sauce | Lettuce | Onion | Patty+Cheese | Middle bun | Sauce | Lettuce | Onion | Gherkins | Patty+Cheese | Top bun',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (510,64,1,'Place ham in large pot. Add onion (halved), carrots (chunked), celery, thyme, peppercorns, and cloves. Cover with cold water.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (511,64,2,'Bring to boil, then reduce to gentle simmer. Cook for 1hr 15min.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (512,64,3,'Turn off heat. Let ham rest in the water for 30 minutes.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (513,64,4,'Preheat oven to 200°C. Remove ham from pot and pat dry thoroughly with kitchen paper.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (514,64,5,'Place ham on baking tray. Mix honey and mustard in small bowl until combined.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (515,64,6,'Brush half the glaze over the ham, getting into any crevices.',NULL,NULL,NULL);
