INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (750,78,0,'CHEF\'S NOTE: We use whole chuck roast instead of pre-cubed stewing beef — it has better marbling and collagen for a richer stew. The overnight salt (dry brine) seasons the meat all the way through, firms the texture so it holds together during braising, and makes the final result more tender.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (751,78,1,'DAY BEFORE: Salt the chuck roast generously on all sides. Place on a rack over a plate, refrigerate uncovered 12-24 hours.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (752,78,2,'Remove chuck from fridge. Pat dry with paper towels. Let sit 30 minutes to take the chill off.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (753,78,3,'Sear the chuck (no oil). Heat heavy pot over high heat until smoking. Sear chuck on all sides until deeply browned — about 3 minutes per side. It will release its own fat. Remove and set aside.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (754,78,4,'Build the base. Reduce heat to medium. Add butter to the rendered fat. Sauté onion and celery 5 minutes until softened. Add garlic, cook 1 minute until fragrant.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (755,78,5,'Add tomato paste. Stir in, cook 2 minutes to caramelize.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (756,78,6,'Braise the chuck. Return beef to pot. Add stock, Worcestershire, bay leaves, and thyme. Bring to a boil, then reduce to a bare simmer. Cover and cook 2.5-3 hours until fork-tender.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (757,78,7,'Skim the fat. Remove chuck to a board. Skim fat from the surface of the liquid with a spoon (or chill overnight and lift off solidified fat).',NULL,NULL,NULL);
