INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (819,84,6,'Sear beef: Add beef in single layer. Do not touch for 30 seconds until seared. Flip, sear 30 seconds more. Remove to plate (beef will be 70% cooked).','Do not overcrowd - sear in batches if needed',NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (820,84,7,'Cook aromatics: Add remaining oil. Add garlic, ginger, spring onion whites. Stir 30 seconds until fragrant.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (821,84,8,'Add vegetables: Add onion, cook 1 minute. Add peppers, cook 2 minutes until crisp-tender.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (822,84,9,'Finish: Return beef to wok. Add dry sherry (it will sizzle). Pour sauce over, toss. Add cornflour slurry, toss until glossy and thickened (30 seconds).','The sizzle when adding sherry is wok hei',NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (823,84,10,'Serve immediately over jasmine rice, topped with spring onion greens.',NULL,NULL,NULL);
