INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1292,134,1,'Prep tamarind sauce: Break 30g tamarind from the block into a small bowl. Add 2 tbsp hot water and mix until smooth paste forms. Push through a sieve to remove seeds. Mix strained tamarind with soy sauce,   \n  honey, lime juice, and chilli flakes.','Cock Brand Pure Tamarind block from Asia Market is ideal — 100% tamarind',NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1293,134,2,'Make slurry: Mix cornflour with 2 tbsp cold water in a separate bowl. Set aside.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1294,134,3,'Velvet chicken: Slice into thin strips (~1cm wide). Toss with a pinch of salt and 1 tsp of the cornflour slurry.','Velveting keeps the chicken silky and juicy',NULL,NULL);
