INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1297,134,6,'Stir fry veg: Same wok, high heat. Add carrot and red pepper — stir fry 2 minutes until slightly charred but still crunchy. Add red cabbage and spring onion whites — stir fry 1 minute until cabbage just     \n  wilts.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1298,134,7,'Aromatics: Add garlic and ginger — stir fry 30 seconds until fragrant.',NULL,NULL,NULL);
