INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1592,200,2,'Slice chicken breast into 1″ medallions, season with salt, pepper, oregano and chilli flakes. Heat olive oil in a non-stick pan over medium-high; sear chicken 3 min each side until just cooked through. Remove and rest.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1593,200,3,'Same pan, medium heat: add minced garlic and chopped sundried tomatoes, cook 60 seconds until fragrant (do not brown the garlic).\n  Pour in the chicken stock and any juices from the rested chicken. Bring to a hard simmer and reduce until the liquid just coats the pan and barely\n  covers the tomatoes (about 3-4 min); it should look glossy, not soupy.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1594,200,4,'In a small bowl, whisk the cornflour with 1 tbsp cold water to make a smooth slurry; set aside. Drop the pan heat to low. Blend the\n   cottage cheese smooth (immersion blender in a small jug, ~20 sec). Whisk the cottage cheese into the pan along with the grated parmesan and 2 tbsp of\n   the rice cooking water. Pour in the cornflour slurry and stir constantly for 60-90 seconds until the sauce thickens and coats the back of a spoon -\n  it should be glossy, not pourable, and never bubble (above ~80 C the cottage cheese will split). Stir in the baby spinach to wilt (1 min). Return the\n  chicken plus its resting juices to coat in the sauce. Taste and adjust salt and pepper. Off heat, scatter torn basil to serve.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1595,200,5,'Spoon the rice into warm bowls, ladle over the Tuscan chicken and sauce, finish with a crack of black pepper and an extra pinch of\n  chilli flakes if you like heat.',NULL,NULL,NULL);
