INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1629,189,2,'Heat olive oil in a large pot over medium heat. Sweat diced onion, carrot, and celery 5 min until soft and translucent. Add\n  minced garlic, thyme, oregano, salt, and pepper; cook 1 min until fragrant.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1630,189,3,'Add diced chicken and stir 2 min until surfaces turn opaque. Pour in vegetable stock, drained butter beans, and the bay leaf.\n  Bring to a boil, then reduce to a simmer 10 min until chicken is cooked through.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1631,189,4,'Tear the prepared fresh pasta into rough 4–5 cm pieces and drop into the simmering broth. Cook 2–3 min until just tender.',NULL,36,'Stir in the cooked dried spaghetti and warm through 1 min.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1632,189,5,'Remove the bay leaf. Stir in baby spinach and simmer 1 min until wilted. Off the heat, stir through the juice of the lemon half\n  and the chopped parsley. Taste and adjust seasoning; rest 2 min.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1633,189,6,'Ladle into two bowls, top with grated parmesan, and finish with a drizzle of extra-virgin olive oil.',NULL,NULL,NULL);
