INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1676,57,1,'Cook the rice: Rinse rice under cold water until water runs clear. Cook in salted water per packet instructions. When done, fluff with a fork, stir in half the lime juice\n  and half the chopped coriander. Cover and set aside.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1677,57,2,'Season the chicken: Pat thighs completely dry with kitchen paper. Mix cumin, smoked paprika, half the salt, and the pepper in a bowl. Coat the chicken generously and rub\n  the spice mix into both sides.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1678,57,3,'Sear the chicken: Heat a heavy non-stick or cast-iron pan over medium-high until it just begins to smoke. Add the olive oil, swirl, then lay in the thighs. Sear undisturbed\n   for 4 min to build a hard char, flip, and cook a further 4-5 min until the internal temperature reaches 74 C. Transfer to a board, rest 5 min, slice against the grain and reserve\n  any juices on the board.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1679,57,4,'Bloom the beans: In a small pot, warm 1 tsp olive oil (taken from the recipe oil) over medium heat. Add 1 minced garlic clove and a pinch of cumin; cook 30 seconds until\n  fragrant. Tip in the drained black beans plus 3 tbsp of their tin liquid; simmer 3 min until glossy and just thickened. Finish with a squeeze of lime and a pinch of salt.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1680,57,5,'Make quick pico: Finely dice the tomato and remaining onion. Toss with the remaining lime juice and remaining coriander; season with a pinch of salt.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1681,57,6,'Prep the avocado: Halve, remove the pit, and slice or roughly mash. Squeeze the remaining lime over it and season with salt.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1682,57,7,'Assemble bowls: Divide the cilantro-lime rice between two bowls. Top with sliced chicken (spooning the reserved resting juices over the top), the glossy black beans, pico\n  de gallo, avocado, and a generous dollop of Greek yogurt.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1683,58,1,'Cook the rice: Rinse rice under cold water until water runs clear. Cook in salted water per packet instructions. When done, fluff with a fork, stir in half the lime juice\n  and half the chopped coriander. Cover and set aside.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1684,58,2,'Season the chicken: Pat thighs completely dry with kitchen paper. Mix cumin, smoked paprika, half the salt, and the pepper in a bowl. Coat the chicken generously and rub\n  the spice mix into both sides.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1685,58,3,'Sear the chicken: Heat a heavy non-stick or cast-iron pan over medium-high until it just begins to smoke. Add the olive oil, swirl, then lay in the thighs. Sear undisturbed\n   for 4 min to build a hard char, flip, and cook a further 4-5 min until the internal temperature reaches 74 C. Transfer to a board, rest 5 min, slice against the grain and reserve\n  any juices on the board.',NULL,NULL,NULL);
