INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1696,59,7,'Assemble bowls: Divide the cilantro-lime rice between two bowls. Top with sliced chicken (spooning the reserved resting juices over the top), the glossy black beans, pico\n  de gallo, and avocado. Scatter the grated cheddar over the warm chicken so it just melts, then finish with a generous dollop of Greek yogurt.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1697,37,1,'Prepare the tomato sauce according to the linked recipe. Use 160g for this dish.',NULL,12,'Use 160g store-bought tomato/marinara sauce (e.g. Mutti, Dolmio) brought up to a gentle simmer with 1 minced garlic clove in a splash of olive oil.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1698,37,2,'Prepare the fresh pasta according to the linked recipe. Use 175g dough total (~87g per person).',NULL,36,'Cook 140g dried fettuccine or tagliatelle according to package directions. Reserve 200ml cooking water before draining.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1699,37,3,'Season chicken breast with salt and pepper. Heat olive oil in a pan over medium-high heat. Cook chicken 5-6 minutes per side until golden and cooked through\n  (74C internal). Transfer to a board to rest 5 minutes, then slice.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1700,37,4,'In the same pan over medium heat, add minced garlic and cook 30 seconds until fragrant — do not let it colour.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1701,37,5,'Pour in the prepared tomato sauce. Add smoked paprika. Simmer gently for 2 minutes to marry the flavours.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1702,37,6,'Reduce heat to low. Stir in the milk and grated parmesan until the parmesan melts and the sauce comes together. Pour in any juices the chicken released on the\n  board.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1703,37,7,'Add the cooked pasta to the pan with a splash of pasta water (60-80ml) and toss until the sauce coats every strand and looks glossy. Add more pasta water in\n  small splashes if it tightens.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1704,37,8,'Off the heat, tear in the fresh basil. Taste and adjust salt.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1705,37,9,'Plate, top with sliced chicken, and finish with cracked black pepper.',NULL,NULL,NULL);
