INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1724,202,1,'Peel and slice the potatoes into 3 mm rounds (mandoline preferred). Halve and thinly slice the onion. Smash\n  and finely chop the garlic.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1725,202,2,'Add 1 tbsp olive oil to a 24 cm non-stick pan over medium-low heat. When it shimmers, add the potatoes, onion,\n   and garlic with a pinch of the salt. Toss to coat — every slice should look glossed.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1726,202,3,'Cover the pan and cook 20–25 min over low heat, lifting the lid to stir every 3–4 min, until the potatoes are\n  completely tender and yield when pressed with a spoon. They must not brown — if they\'re colouring, lower the heat. The pan will look fairly dry by the end; that\'s correct (the oil is in\n  the potatoes).',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1727,202,4,'Crack the eggs into a large bowl with the remaining salt and the smoked paprika. Beat until just combined — no\n   need to froth.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1728,202,5,'Flake the drained tuna in by hand, breaking up the big chunks. Fold gently. Taste the mix and adjust salt —\n  tuna brands vary a lot.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1729,202,6,'Tip the warm potatoes and onion straight from the pan into the bowl. Fold to coat every slice in egg. Stand 5\n  min so the potatoes drink in the egg.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1730,202,7,'Return the pan to medium heat (no extra oil — the residue is enough). When warm, pour in the mixture and\n  spread evenly with a spatula. Cook 4–5 min, running the spatula around the rim, until edges are set and the base is pale gold. The top will still be wet; the rim should feel tacky-dry.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1731,202,8,'The flip: Place a flat plate (larger than the pan) over the pan. With one hand on the plate, one on the\n  handle, invert in a single confident motion. Slide the tortilla back into the pan raw-side-down. Tuck the edges in with the spatula. Cook 3–4 min more — the centre should give a little when\n  pressed (carry-over finishes it).',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1732,202,9,'Slide onto a serving plate. Rest 5 min. Scatter the chopped parsley. Cut into wedges; serve warm or at room\n  temperature.',NULL,NULL,NULL);
