INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1751,205,1,'Heat oven to 210 C (200 C fan). Pour ~10 g of the olive oil (about 2 tsp) into a small heavy oven-proof pan (cast iron or steel) and slide it in to preheat with the oven.','The pan must be properly hot before the chicken hits it - that is what makes the crust.',NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1752,205,2,'Scrub the potatoes and cut into wedges ~1.5 cm thick at the spine. Toss with the remaining ~4 g olive oil (about 1 tsp) and a small pinch of salt. Air-fry at 200 C for 20-22 min, tossing once at the halfway mark, until deep golden and crisp at the edges.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1753,205,3,'Prepare the Milk Bread crumbs according to the linked recipe. Tear 50 g of stale or lightly-toasted milk bread and pulse in a food processor to coarse crumbs.',NULL,26,'Substitute 50 g of store-bought panko crumbs.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1754,205,4,'Slice the chicken breast against the grain into ~1 cm strips. Pat each strip very dry on kitchen paper - the wet mix will not grip a wet surface.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1755,205,5,'In a bowl, whisk the egg, soy sauce, Worcestershire sauce, salt, garlic granules and onion powder until smooth. Tip the chicken strips in and turn to coat thoroughly.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1756,205,6,'Spread the seasoned crumbs on a plate. Lift each strip out of the wet mix, let excess drip back into the bowl, then press both sides firmly into the crumbs.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1757,205,7,'Pull the hot pan from the oven - the oil should shimmer. Lay the crumbed strips in - you should hear a sharp sizzle. Do not crowd; use two pans if needed. Return to the oven for 7 min, then flip each strip and roast 5-7 min more until the crust is deep golden and the chicken reaches 74 C internal.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1758,205,8,'Rest the dippers 3 min on a wire rack (not paper towel - keeps the crust crisp). Serve with the wedges, a lemon wedge, and your dip of choice (ketchup, sriracha mayo, or honey-mustard - not counted in macros).',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1759,206,1,'Heat oven to 210 C (200 C fan). Pour ~14 g of the olive oil (about 1 tbsp) into a small heavy oven-proof pan (cast iron or steel) and slide it in to preheat with the oven.','The pan must be properly hot before the chicken hits it - that is what makes the crust.',NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1760,206,2,'Scrub the potatoes and cut into wedges ~1.5 cm thick at the spine. Toss with the remaining ~7 g olive oil (about 1.5 tsp) and a small pinch of salt. Air-fry at 200 C for 22-24 min, tossing once at the halfway mark, until deep golden and crisp at the edges.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1761,206,3,'Prepare the Milk Bread crumbs according to the linked recipe. Tear 60 g of stale or lightly-toasted milk bread and pulse in a food processor to coarse crumbs.',NULL,26,'Substitute 60 g of store-bought panko crumbs.');
