INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1765,206,7,'Pull the hot pan from the oven - the oil should shimmer. Lay the crumbed strips in - you should hear a sharp sizzle. Do not crowd; use two pans if needed. Return to the oven for 8 min, then flip each strip and roast 6-7 min more until the crust is deep golden and the chicken reaches 74 C internal.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1766,206,8,'Rest the dippers 3 min on a wire rack (not paper towel - keeps the crust crisp). Serve with the wedges, a lemon wedge, and your dip of choice (ketchup, sriracha mayo, or honey-mustard - not counted in macros).',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1767,207,1,'Heat oven to 210 C (200 C fan). Pour ~19 g of the olive oil (about 1 tbsp + 1 tsp) into a small heavy oven-proof pan (cast iron or steel) and slide it in to preheat with the oven.','The pan must be properly hot before the chicken hits it - that is what makes the crust.',NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1768,207,2,'Scrub the potatoes and cut into wedges ~1.5 cm thick at the spine. Toss with the remaining ~9 g olive oil (about 2 tsp) and a small pinch of salt. Air-fry at 200 C for 24-26 min, tossing once at the halfway mark, until deep golden and crisp at the edges.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1769,207,3,'Prepare the Milk Bread crumbs according to the linked recipe. Tear 70 g of stale or lightly-toasted milk bread and pulse in a food processor to coarse crumbs.',NULL,26,'Substitute 70 g of store-bought panko crumbs.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1770,207,4,'Slice the chicken breast against the grain into ~1 cm strips. Pat each strip very dry on kitchen paper - the wet mix will not grip a wet surface.',NULL,NULL,NULL);
