INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1773,207,7,'Pull the hot pan from the oven - the oil should shimmer. Lay the crumbed strips in - you should hear a sharp sizzle. Do not crowd; use two pans if needed. Return to the oven for 8 min, then flip each strip and roast 7-8 min more until the crust is deep golden and the chicken reaches 74 C internal.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1774,207,8,'Rest the dippers 3 min on a wire rack (not paper towel - keeps the crust crisp). Serve with the wedges, a lemon wedge, and your dip of choice (ketchup, sriracha mayo, or honey-mustard - not counted in macros).',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1775,91,1,'Cover the dried rice noodles in room-temperature water for 30-45 minutes until pliable but still firm. Drain well.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1776,91,2,'Prepare the sauce: soak the tamarind in 3 tbsp warm water for 5 minutes, then mash and strain out the fibres. Mix the tamarind water with the fish sauce, soy sauce, sugar and chilli flakes until the sugar dissolves.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1777,91,3,'Slice the chicken breast into thin strips. Peel and devein the prawns if needed. Mince the garlic, slice the shallot, and cut the spring onions into 2-inch pieces.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1778,91,4,'Heat half the oil in a wok over high heat until smoking. Stir-fry the chicken 2-3 minutes until cooked through. Remove and set aside.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1779,91,5,'Add the remaining oil. Stir-fry the prawns 1-2 minutes until just pink. Remove and set aside with the chicken.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1780,91,6,'Add the garlic and shallot to the wok. Fry 30 seconds until fragrant.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1781,91,7,'Push the aromatics to the side. Crack the egg(s) into the wok and scramble loosely.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1782,91,8,'Add the drained noodles and the sauce. Toss constantly for 2-3 minutes until the noodles absorb the sauce and soften.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1783,91,9,'Return the chicken and prawns to the wok. Add half the bean sprouts and the spring onions. Toss for 30 seconds.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1784,91,10,'Taste and adjust before plating: aim for a balanced sweet-sour-salty flavour with gentle heat. Add lime for sourness, a splash of fish sauce for salt, a pinch of sugar to round it off, or more chilli for heat.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1785,91,11,'Serve topped with the remaining bean sprouts, crushed peanuts, and a lime wedge.',NULL,NULL,NULL);
