INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1811,44,1,'Prepare the pizza dough according to the linked recipe. Use 210g dough. Let it come to room temperature before rolling.',NULL,11,'Use 210g store-bought pizza dough, brought to room temperature.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1812,44,2,'Melt 3g of the butter in a wide pan over medium-low heat. Add the sliced onion and a pinch of salt and cook 12-15 minutes, stirring now and then, until deep gold, sweet and jammy — not merely softened. Scrape into a bowl and reserve the rest of the butter.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1813,44,3,'Turn the heat to medium-high. Add the beef mince to the dry pan in a single layer and leave it alone for 3-4 minutes until a brown crust forms and it sticks to the pan. Only then break it up and cook 2-3 minutes more until no pink remains. Tip off any liquid.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1814,44,4,'Stir the onions back through the mince with the Italian seasoning. Taste and adjust the salt now — once it is sealed in the dough you cannot fix it.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (1815,44,5,'Roll the dough into a 28 x 18cm rectangle on a floured surface. Spread 50g pizza sauce over it, leaving a 2cm border. Scatter over the mozzarella, then the mince and onion, then the parmesan.',NULL,12,'Roll the dough into a 28 x 18cm rectangle. Spread 50g store-bought pizza sauce over it, leaving a 2cm border. Scatter over the mozzarella, then the mince and onion, then the parmesan.');
