INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (2122,254,4,'Return the meatballs to the sauce, cover, and simmer 15 minutes until they reach 74°C (165°F) internally and the sauce has thickened slightly (turkey must be cooked through, unlike beef which can be served pink).',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (2123,254,5,'Meanwhile, cook the spaghetti according to package directions, drain, reserving a splash of pasta water to loosen the sauce if needed.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (2124,254,6,'Toss the spaghetti with the sauce and meatballs, taste and adjust seasoning, then scatter with parmesan and fresh basil to serve.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (2125,255,1,'In a bowl, combine the turkey mince, breadcrumbs, egg, half the garlic, oregano, salt, and pepper. Mix gently and shape into ~14 meatballs -- do not overwork the mixture or they will turn dense.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (2126,255,2,'Heat half the olive oil in a large pan over medium-high heat. Brown the meatballs on all sides, 5-6 minutes, then remove.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (2127,255,3,'Add the remaining olive oil and garlic to the pan, cook 30 seconds until fragrant. Stir in the tomato passata and bring to a simmer.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (2128,255,4,'Return the meatballs to the sauce, cover, and simmer 15 minutes until they reach 74°C (165°F) internally and the sauce has thickened slightly (turkey must be cooked through, unlike beef which can be served pink).',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (2129,255,5,'Meanwhile, cook the spaghetti according to package directions, drain, reserving a splash of pasta water to loosen the sauce if needed.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (2130,255,6,'Toss the spaghetti with the sauce and meatballs, taste and adjust seasoning, then scatter with parmesan and fresh basil to serve.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (2131,256,1,'Heat the olive oil in a large pan over medium heat. Add the onion, carrot, and celery, and cook 6-8 minutes until softened.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (2132,256,2,'Add the garlic and cook 30 seconds until fragrant.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (2133,256,3,'Add the turkey mince, breaking it up with a spoon, and cook 5-6 minutes until no longer pink.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (2134,256,4,'Stir in the tomato paste and cook 1 minute, then add the tinned tomatoes, chicken stock, sugar, oregano, and bay leaf. Bring to a simmer.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (2135,256,5,'Simmer uncovered for 30-35 minutes, stirring occasionally, until the sauce has thickened and the turkey reaches 74°C (165°F) internally.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (2136,256,6,'Meanwhile, cook the spaghetti according to package directions and drain.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (2137,256,7,'Remove the bay leaf, taste and adjust seasoning, then toss the spaghetti with the sauce. Scatter with parmesan and fresh basil to serve.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (2138,257,1,'Heat the olive oil in a large pan over medium heat. Add the onion, carrot, and celery, and cook 6-8 minutes until softened.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (2139,257,2,'Add the garlic and cook 30 seconds until fragrant.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (2140,257,3,'Add the turkey mince, breaking it up with a spoon, and cook 5-6 minutes until no longer pink.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (2141,257,4,'Stir in the tomato paste and cook 1 minute, then add the tinned tomatoes, chicken stock, sugar, oregano, and bay leaf. Bring to a simmer.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (2142,257,5,'Simmer uncovered for 30-35 minutes, stirring occasionally, until the sauce has thickened and the turkey reaches 74°C (165°F) internally.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (2143,257,6,'Meanwhile, cook the spaghetti according to package directions and drain.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (2144,257,7,'Remove the bay leaf, taste and adjust seasoning, then toss the spaghetti with the sauce. Scatter with parmesan and fresh basil to serve.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (2145,258,1,'Heat the olive oil in a large pan over medium heat. Add the onion, carrot, and celery, and cook 6-8 minutes until softened.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (2146,258,2,'Add the garlic and cook 30 seconds until fragrant.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (2147,258,3,'Add the turkey mince, breaking it up with a spoon, and cook 5-6 minutes until no longer pink.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (2148,258,4,'Stir in the tomato paste and cook 1 minute, then add the tinned tomatoes, chicken stock, sugar, oregano, and bay leaf. Bring to a simmer.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (2149,258,5,'Simmer uncovered for 30-35 minutes, stirring occasionally, until the sauce has thickened and the turkey reaches 74°C (165°F) internally.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (2150,258,6,'Meanwhile, cook the spaghetti according to package directions and drain.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (2151,258,7,'Remove the bay leaf, taste and adjust seasoning, then toss the spaghetti with the sauce. Scatter with parmesan and fresh basil to serve.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (2152,266,1,'Soak the rice noodles in warm water for 15-20 minutes, until pliable but still firm at the core. Drain well and toss with a few drops of the sesame oil so they do not clump.','Never boil them. They finish cooking in the wok, and noodles that went into boiling water arrive there already soft and break into mush the moment you toss them.',NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (2153,266,2,'Slice the chicken thinly on the bias and season with the salt and white pepper.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (2154,266,3,'Chop everything before the pan goes on: onion into thin wedges, pepper into strips, spring onions into 3 cm lengths, garlic sliced, ginger cut into matchsticks. Combine the curry powder, turmeric, cumin and chilli flakes in a small bowl.','A stir-fry gives you no time to catch up once the pan is hot. Everything within arm\'s reach before you light the hob.',NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (2155,266,4,'Beat the eggs. Heat the pan over high heat, add a third of the coconut oil, and scramble the eggs in about 30 seconds while they are still slightly wet. Tip them onto a plate.','Pull them while they look underdone - they will finish in the residual heat and again when they go back into the wok.',NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (2156,266,5,'Same pan, still high, remaining coconut oil. Chicken in a single layer, 90 seconds undisturbed, then toss for 1 minute until just opaque. Onto the plate with the eggs, juices and all.','Crowding the pan makes the chicken steam instead of sear. Two batches if it will not sit in one layer.',NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (2157,266,6,'Turn the heat down to medium. Add the garlic and ginger for 20 seconds, then tip in the spice mix and stir it through the oil for 45-60 seconds, until it darkens a shade and smells nutty rather than dusty.','This is the step the whole dish is built on. Curry powder added later, into liquid, stays chalky no matter how long it cooks - it needs fat and direct heat to bloom.',NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (2158,266,7,'Heat back to high. Add the onion and pepper and stir-fry for 2 minutes - they should keep some bite.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (2159,266,8,'Add the noodles and the soy sauce, then the stock a splash at a time, lifting and turning until every strand is coated yellow and no liquid pools at the base of the pan.','Use tongs or chopsticks, never a spoon - a spoon shreds the noodles. And go easy on the stock: this dish should finish dry and separate, not saucy.',NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (2160,266,9,'Return the chicken, the egg and every drop of juice from the plate. Add the bean sprouts and spring onions and toss for 30 seconds only.','Those plate juices are concentrated flavour. And the sprouts are there for crunch - another minute in the pan and they go limp.',NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (2161,266,10,'Off the heat, stir through the remaining sesame oil, the lime juice and the coriander.','Sesame oil is a finishing oil - its flavour breaks down over high heat. Off the hob, always last.',NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (2162,266,11,'Taste before it leaves the pan. Tastes dusty? The spices needed longer at step 6 - bloom a pinch more in a teaspoon of oil and stir it through. Flat? A little more soy. Heavy? More lime.',NULL,NULL,NULL);
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `tip`, `linked_recipe_id`, `alt_instruction`) VALUES (2163,267,1,'Soak the rice noodles in warm water for 15-20 minutes, until pliable but still firm at the core. Drain well and toss with a few drops of the sesame oil so they do not clump.','Never boil them. They finish cooking in the wok, and noodles that went into boiling water arrive there already soft and break into mush the moment you toss them.',NULL,NULL);
