INSERT INTO `recipe_families` (`id`, `family_name`, `description`, `created_at`, `updated_at`) VALUES (1,'Porridge with Berries & Nuts','Creamy oat porridge topped with honey, peanut butter, mixed berries, and chopped nuts','2025-12-19 08:22:57','2025-12-19 08:22:57');
INSERT INTO `recipe_families` (`id`, `family_name`, `description`, `created_at`, `updated_at`) VALUES (2,'Frozen Banana Smoothie','Thick and creamy frozen banana smoothie with peanut butter and milk','2025-12-19 08:22:57','2026-08-18 10:51:09');
INSERT INTO `recipe_families` (`id`, `family_name`, `description`, `created_at`, `updated_at`) VALUES (3,'Irish Chicken Curry','Sweet and mild chicken curry with banana, warm spices, roasted sweet potato, and peas. Served over rice.','2025-12-19 08:22:57','2025-12-19 08:22:57');
INSERT INTO `recipe_families` (`id`, `family_name`, `description`, `created_at`, `updated_at`) VALUES (4,'Pizza','Homemade pizza with from-scratch dough and tomato sauce. All variants include chicken and mushrooms. Balanced 2 adds pepperoni. Sizes: Light 7\", Moderate 8\", Balanced 9\".','2025-12-19 08:23:02','2026-01-18 18:09:56');
INSERT INTO `recipe_families` (`id`, `family_name`, `description`, `created_at`, `updated_at`) VALUES (5,'Chicken Satay','Thai-style grilled chicken skewers with onion and red pepper, served with a creamy peanut dipping sauce over jasmine rice.','2025-12-19 08:23:04','2025-12-19 08:23:04');
INSERT INTO `recipe_families` (`id`, `family_name`, `description`, `created_at`, `updated_at`) VALUES (6,'Black Bean Chicken Wrap','Grilled spiced chicken with smoky black bean dip, Greek yogurt sauce, fresh veg, and rice wrapped in homemade flatbread.','2025-12-19 08:23:08','2025-12-19 08:23:08');
INSERT INTO `recipe_families` (`id`, `family_name`, `description`, `created_at`, `updated_at`) VALUES (7,'Chicken & Vegetable Soup','Hearty blended soup with chunky chicken and peas, topped with crispy roasted baby potatoes.','2025-12-19 08:23:10','2025-12-19 08:23:10');
INSERT INTO `recipe_families` (`id`, `family_name`, `description`, `created_at`, `updated_at`) VALUES (8,'Salmon Sandwich','Simple salmon sandwich with homemade milk bread, salted butter, and fresh lettuce. Moderate = 1 sandwich per person, Balanced = 2 sandwiches per person.','2025-12-19 08:23:13','2025-12-22 08:11:50');
INSERT INTO `recipe_families` (`id`, `family_name`, `description`, `created_at`, `updated_at`) VALUES (9,'Lentil Stew','Hearty stew with brown lentils, tomatoes, carrots, and pak choi, spiced with smoked paprika and cumin. Moderate and Balanced variants include crispy chorizo.','2025-12-19 08:23:15','2025-12-22 08:11:50');
INSERT INTO `recipe_families` (`id`, `family_name`, `description`, `created_at`, `updated_at`) VALUES (10,'Lentil Stuffed Peppers','Roasted red peppers stuffed with lentil bolognese - a hearty vegetarian take on the Italian classic.','2025-12-19 08:23:17','2025-12-19 08:23:17');
INSERT INTO `recipe_families` (`id`, `family_name`, `description`, `created_at`, `updated_at`) VALUES (11,'Pink Sauce Pasta','Creamy cashew-based pink sauce with smoked paprika, parmesan, and sliced chicken over fresh pasta.','2025-12-19 08:23:21','2025-12-19 08:23:21');
INSERT INTO `recipe_families` (`id`, `family_name`, `description`, `created_at`, `updated_at`) VALUES (12,'Chicken Tikka Masala','Creamy tomato-based curry with tender chicken, Greek yogurt, and aromatic spices. Served over jasmine rice.','2025-12-19 08:23:22','2025-12-19 08:23:22');
INSERT INTO `recipe_families` (`id`, `family_name`, `description`, `created_at`, `updated_at`) VALUES (13,'Stromboli','Rolled pizza dough stuffed with seasoned beef, mozzarella, parmesan, grilled onion, and pizza sauce. Brushed with garlic and Italian herb olive oil.','2025-12-19 08:23:25','2025-12-19 08:23:25');
